// A Magic Patterns design URL, or a Magic OS file URL (/os/<osId>?file=<fileId>).
url?: string,
// A Magic Patterns design editor id.
editorId?: string,
// Regex pattern to search for in file contents.
query: string,
// Optional case-insensitive substring filter for file names.
