viewport?: "desktop" | "tablet" | "mobile",
// Shoot the whole page at full size, up to 4000px tall, rather than one window of it. Without it, a page that runs past the window is zoomed out to fit, down to 67%, and a longer one shows its top. Default false.
fullPage?: boolean,
// Show one element rather than the whole screen. Name it by source — `path` and `line` (or `text`) — or, failing that, by a CSS `selector`.
element?: {
// The OS file whose source `path` is in, when it is not the one being previewed — a frame, say, previewing its prototype.
osFile?: string,
// The file the element is written in, within that OS file, as `read_file` takes it, e.g. "index.tsx".
path?: string,
// The 1-based line its opening tag starts on, as `read_file` numbers it.
line?: integer,
// Instead of `line`: a snippet of that file inside the element, e.g. its heading text. The innermost element around its first occurrence is the one meant.
text?: string,
// Instead of `path`: a CSS selector the element matches on the page.
